using System; using System.Collections.Generic; using System.Linq; using System.Text.Json; using System.Threading; using System.Threading.Tasks; using Parcs.Agent.Runtime;

public class Subinterval : IAgentComputation
{
    public class Result { public double value { get; set; } }
    public Task<AgentLayerResult> ExecuteAsync(AgentLayerInput input, CancellationToken ct)
    {
        int k = int.Parse(input.WorkerInput);
        double a = 8.0 * k / 32.0;
        double b = 8.0 * (k + 1) / 32.0;
        const int n = 10000;
        double h = (b - a) / n;
        double sum = F(a) + F(b);
        for (int i = 1; i < n; i++)
        {
            double x = a + i * h;
            sum += (i % 2 == 0 ? 2.0 : 4.0) * F(x);
        }
        double value = sum * h / 3.0;
        return Task.FromResult(AgentLayerResult.Ok(JsonSerializer.Serialize(new Result { value = value })));
    }
    private static double F(double x) => Math.Exp(-x / 4.0) * Math.Cos(x + 0.5 * Math.Sin(2.0 * x));
}

public class Reduce : IAgentComputation
{
    public class Result { public double value { get; set; } }
    public Task<AgentLayerResult> ExecuteAsync(AgentLayerInput input, CancellationToken ct)
    {
        double total = 0.0;
        for (int j = 0; j < 32; j++)
        {
            var outputs = input.GetPreviousOutputs(j);
            foreach (var json in outputs)
            {
                if (json == null) continue;
                var item = JsonSerializer.Deserialize<Result>(json);
                total += item.value;
            }
        }
        return Task.FromResult(AgentLayerResult.Ok(JsonSerializer.Serialize(new Result { value = total })));
    }
}

